/* Output policy cluster */
static void jq_session_set_dumpopts(jq_session *s, int dumpopts) {
  if (s == NULL)
    return;
  s->dumpopts = dumpopts;
}

static int jq_session_dumpopts(jq_session *s) {
  if (s == NULL)
    return 0;
  return s->dumpopts;
}

static void jq_session_add_dump_flag(jq_session *s, int bit) {
  if (s == NULL)
    return;
  s->dumpopts |= bit;
}

static void jq_session_clear_dump_flag(jq_session *s, int bit) {
  if (s == NULL)
    return;
  s->dumpopts &= ~bit;
}

static void jq_session_set_compact_output(jq_session *s) {
  if (s == NULL)
    return;
  s->dumpopts &= ~(JV_PRINT_TAB | JV_PRINT_INDENT_FLAGS(7));
  s->pretty_indent = 0;
  s->tab_indent = 0;
}

static void jq_session_set_tab_output(jq_session *s) {
  if (s == NULL)
    return;
  s->dumpopts &= ~JV_PRINT_INDENT_FLAGS(7);
  s->dumpopts |= JV_PRINT_TAB | JV_PRINT_PRETTY;
  s->tab_indent = 1;
  s->pretty_indent = 1;
}

static void jq_session_set_indent_output(jq_session *s, int indent) {
  if (s == NULL)
    return;
  s->dumpopts &= ~(JV_PRINT_TAB | JV_PRINT_INDENT_FLAGS(7));
  s->dumpopts |= JV_PRINT_INDENT_FLAGS(indent);
  s->pretty_indent = indent;
  s->tab_indent = 0;
}

static void jq_session_force_color(jq_session *s) {
  if (s == NULL)
    return;
  s->color_forced = 1;
  s->color_disabled = 0;
  s->dumpopts |= JV_PRINT_COLOR;
}

static void jq_session_disable_color(jq_session *s) {
  if (s == NULL)
    return;
  s->color_disabled = 1;
  s->color_forced = 0;
  s->dumpopts &= ~JV_PRINT_COLOR;
}

static void jq_session_set_ascii_output(jq_session *s) {
  if (s == NULL)
    return;
  s->ascii_output = 1;
  s->dumpopts |= JV_PRINT_ASCII;
}

static void jq_session_set_sorted_output(jq_session *s) {
  if (s == NULL)
    return;
  s->sorted_output = 1;
  s->dumpopts |= JV_PRINT_SORTED;
}

static void jq_session_note_stdout_tty(jq_session *s, int is_tty) {
  if (s == NULL)
    return;
  s->stdout_tty = is_tty;
  if (is_tty)
    s->dumpopts |= JV_PRINT_ISATTY;
}

static int jq_session_stdout_is_tty(jq_session *s) {
  return s != NULL && s->stdout_tty;
}

static int jq_session_color_forced(jq_session *s) {
  return s != NULL && s->color_forced;
}

static int jq_session_color_disabled(jq_session *s) {
  return s != NULL && s->color_disabled;
}

static int jq_session_ascii_output_enabled(jq_session *s) {
  return s != NULL && s->ascii_output;
}

static int jq_session_sorted_output_enabled(jq_session *s) {
  return s != NULL && s->sorted_output;
}

static int jq_session_pretty_indent(jq_session *s) {
  if (s == NULL)
    return 0;
  (void)s->dumpopts;
  return s->pretty_indent;
}

static int jq_session_tab_indent(jq_session *s) {
  return s != NULL && s->tab_indent;
}


